/// <summary>
/// Document handler for lookup pages.
/// </summary>
public class TFMLookup extends TFMDocumentHandler
{
}

Method.Source:
public Set getDocumentTypes()
{
    Set retMap = new Set(Types::String);
    retMap.add(subStr(classStr(TFMLookup),4,100));
    return retMap;
}

public XML getResult()
{
    XML ret;
    XmlElement  tmpRootElement;

    if (resultXml == null)
    {
        return '';
    }

    tmpRootElement = resultXml.firstChild();

    // Return the inner XML to remove the temporary root element
    // The framework inserts this XML in the <responseData> element
    // <response>
    //   <responseData>
    //     Lookup response data is placed here
    //   </responseData>
    // </response>
    ret  = tmpRootElement.innerXml();

    return ret;
}

private void findClass(TFMDocumentContentSubject _contentType, TFMDocumentTypeId _documentType = subStr(classStr(TFMLookup),4,100))
{
    TFMDocumentHandler          docHandler;
    DictMethod                  Method;
    TFMLookupResponseElement    response;
    ExecutePermission           perm = new ExecutePermission();

    docHandler = this.subHandler();
    if (!docHandler)
    {
        return;
    }
    Method = docHandler.parmMethod();
    docHandler.parmMessageId(messageId);
    docHandler.setRequestObject(request);
    docHandler.setRequestXml(requestXml);
    docHandler.fillInParms();
    docHandler.preProcess();
    perm.assert();
    response = new DictClass(classIdGet(docHandler)).callObject(Method.name(),docHandler);
    response.setRequest(request);
    resultXml = response.getXML();

    resultStr = docHandler.getResultStr();
    CodeAccessPermission::revertAssert();
}

    public TFMDocumentHandler subHandler()
    {
        TFMDocumentTypeAttribute    docTypeAttribute;
        TFMDocumentHandler          docHandler;
        DictMethod                  Method;

		TFMLookupResponseAttribute  attribute = new TFMLookupResponseAttribute(subStr(classStr(TFMLookup),4,100), request.ContentType());
        docTypeAttribute = new TFMDocumentTypeAttribute(subStr(classStr(TFMLookup),4,100), request.ContentType());
        docHandler = TFMGetRegistrationConfiguration::getClassFromSysAttribute(classStr(TFMDocumentHandler), docTypeAttribute);

		if (docHandler == null)
        {
            resultStr = strFmt("@TFM:CouldNotFindAppropriateClass",subStr(classStr(TFMLookup),4,100), request.ContentType());
            return Null;
        }
        Method = TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(docHandler),docTypeAttribute);
        if (!Method)
        {
            Method = TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(docHandler),attribute);
        }        
        if (Method == null)
        {
            resultStr = strFmt("@TFM:CouldNotFindAppropriateMethod",subStr(classStr(TFMLookup),4,100), request.ContentType(),classId2Name(classIdGet(docHandler)));
            return Null;            
		}
        docHandler.parmMethod(Method);
        return docHandler;

    }
